//! The instruction table (hardening proposal 4): per program and discriminator, an instruction's
//! account count and profile groups, generated by `apps/idl-table`. Decoder-free: the checks
//! compare the compiled message with the table and the config, and read nothing else.

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::str::FromStr;

use anyhow::{Context, Result, bail};
use serde::Deserialize;
use sha2::{Digest, Sha256};
use solana_address::Address;
use solana_message::Message;

use crate::checks::{Refusal, refuse};
use crate::payload::hex;

const FORMAT: u32 = 1;

/// `report`: findings are reported and logged, never refused.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Mode {
    Report,
}

impl Mode {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Report => "report",
        }
    }
}

#[derive(Debug)]
pub struct InstructionTable {
    pub path: PathBuf,
    pub mode: Mode,
    programs: Vec<Address>,
    rows: HashMap<(Address, [u8; 8]), Row>,
}

#[derive(Debug)]
struct Row {
    name: String,
    min: usize,
    max: usize,
    /// (signer slot, profile slot) of each profile group.
    profiles: Vec<(usize, usize)>,
}

#[derive(Deserialize)]
struct RawTable {
    format: u32,
    cluster: String,
    programs: Vec<RawProgram>,
    instructions: Vec<RawInstruction>,
}

#[derive(Deserialize)]
struct RawProgram {
    address: String,
}

#[derive(Deserialize)]
struct RawInstruction {
    program: String,
    discriminator: String,
    name: String,
    accounts: RawAccounts,
    profiles: Vec<RawGroup>,
}

#[derive(Deserialize)]
struct RawAccounts {
    min: usize,
    max: usize,
}

#[derive(Deserialize)]
struct RawGroup {
    signer: usize,
    profile: usize,
}

impl InstructionTable {
    /// Reads the table at `path`, refusing it unless its sha256 is `sha256` and it is for `cluster`.
    pub fn load(path: &Path, sha256: &str, mode: Mode, cluster: &str) -> Result<Self> {
        let bytes = std::fs::read(path)
            .with_context(|| format!("instruction_table: reading {}", path.display()))?;
        let actual = hex(&Sha256::digest(&bytes));
        if !actual.eq_ignore_ascii_case(sha256.trim()) {
            bail!(
                "instruction_table: {} has sha256 {actual}, not the configured {sha256}",
                path.display()
            );
        }
        Self::parse(&bytes, path, mode, cluster)
    }

    fn parse(bytes: &[u8], path: &Path, mode: Mode, cluster: &str) -> Result<Self> {
        let at = || format!("instruction_table: {}", path.display());
        let raw: RawTable = serde_json::from_slice(bytes).with_context(at)?;
        if raw.format != FORMAT {
            bail!("{}: format {}, expected {FORMAT}", at(), raw.format);
        }
        if raw.cluster != cluster {
            bail!("{}: for cluster {:?}, not {cluster:?}", at(), raw.cluster);
        }
        let address = |a: &str| {
            Address::from_str(a).map_err(|e| anyhow::anyhow!("{}: address {a:?}: {e}", at()))
        };
        let programs = raw
            .programs
            .iter()
            .map(|p| address(&p.address))
            .collect::<Result<Vec<_>>>()?;
        let mut rows = HashMap::new();
        for i in raw.instructions {
            let program = address(&i.program)?;
            if !programs.contains(&program) {
                bail!("{}: {} names an unlisted program {program}", at(), i.name);
            }
            let Some(disc) = discriminator(&i.discriminator) else {
                bail!(
                    "{}: {}: discriminator {:?} is not 8 hex bytes",
                    at(),
                    i.name,
                    i.discriminator
                );
            };
            if i.accounts.min > i.accounts.max {
                bail!("{}: {}: min accounts above max", at(), i.name);
            }
            let row = Row {
                profiles: i.profiles.iter().map(|g| (g.signer, g.profile)).collect(),
                min: i.accounts.min,
                max: i.accounts.max,
                name: i.name,
            };
            if let Some(old) = rows.insert((program, disc), row) {
                bail!("{}: {} repeats a discriminator", at(), old.name);
            }
        }
        Ok(Self {
            path: path.to_owned(),
            mode,
            programs,
            rows,
        })
    }

    pub fn len(&self) -> usize {
        self.rows.len()
    }

    /// What the table says about `message` for the key `signer` of profile `profile`, in order:
    /// `instructions` (unknown), `accounts` (count) and `profile` (a group the key signs for
    /// names another profile, or the key has none set).
    pub fn findings(
        &self,
        message: &Message,
        signer: &Address,
        profile: Option<&Address>,
    ) -> Vec<Refusal> {
        let keys = &message.account_keys;
        let mut out = Vec::new();
        for (n, ix) in message.instructions.iter().enumerate() {
            let Some(program) = keys.get(usize::from(ix.program_id_index)) else {
                continue;
            };
            if !self.programs.contains(program) {
                continue;
            }
            let disc = ix.data.get(..8).and_then(|d| <[u8; 8]>::try_from(d).ok());
            let Some(row) = disc.and_then(|d| self.rows.get(&(*program, d))) else {
                out.push(refuse(
                    "instructions",
                    format!(
                        "instruction {n} calls {program} with discriminator {}, which the table does not list",
                        disc.map_or_else(|| "(too short)".to_owned(), |d| hex(&d))
                    ),
                ));
                continue;
            };
            let count = ix.accounts.len();
            if count < row.min || count > row.max {
                out.push(refuse(
                    "accounts",
                    format!(
                        "instruction {n} ({}) has {count} accounts; the table allows {} to {}",
                        row.name, row.min, row.max
                    ),
                ));
                continue;
            }
            let slot = |i: usize| ix.accounts.get(i).and_then(|k| keys.get(usize::from(*k)));
            for (s, p) in &row.profiles {
                if slot(*s) != Some(signer) {
                    continue;
                }
                let named = slot(*p);
                let detail = match profile {
                    None => format!(
                        "instruction {n} ({}) acts for profile {} and this key has no profile set",
                        row.name,
                        named.map_or_else(|| "-".to_owned(), ToString::to_string)
                    ),
                    Some(own) if named != Some(own) => format!(
                        "instruction {n} ({}) acts for profile {}, not this key's {own}",
                        row.name,
                        named.map_or_else(|| "-".to_owned(), ToString::to_string)
                    ),
                    Some(_) => continue,
                };
                out.push(refuse("profile", detail));
            }
        }
        out
    }
}

fn discriminator(s: &str) -> Option<[u8; 8]> {
    let bytes: Vec<u8> = s
        .as_bytes()
        .chunks(2)
        .map(|c| {
            std::str::from_utf8(c)
                .ok()
                .and_then(|h| u8::from_str_radix(h, 16).ok())
        })
        .collect::<Option<_>>()?;
    bytes.try_into().ok()
}

#[cfg(test)]
mod tests {
    use super::*;
    use solana_instruction::{AccountMeta, Instruction};

    const GAME: &str = "C4SAgeKLgb3pTLWhVr6NRwWyYFuTR7ZeSXFrzoLwfMzF";

    fn addr(n: u8) -> Address {
        Address::new_from_array([n; 32])
    }

    fn game() -> Address {
        Address::from_str(GAME).unwrap()
    }

    /// `move` (3 to 4 accounts, key at 0 checked against profile 1) and `crank` (2, no group).
    fn text() -> String {
        format!(
            r#"{{"format": 1, "cluster": "zink-testnet", "generator": "test", "from": "test",
            "programs": [{{"name": "sage", "address": "{GAME}", "idl_version": "1", "idl_sha256": "00"}}],
            "instructions": [
              {{"program": "{GAME}", "discriminator": "0102030405060708", "name": "move",
                "accounts": {{"min": 3, "max": 4, "names": ["s", "p", "f", "o"]}}, "signers": [0],
                "profiles": [{{"prefix": "p", "signer": 0, "profile": 1, "key_index": null}}], "funder": null}},
              {{"program": "{GAME}", "discriminator": "1112131415161718", "name": "crank",
                "accounts": {{"min": 2, "max": 2, "names": ["funder", "x"]}}, "signers": [0],
                "profiles": [], "funder": 0}}
            ]}}"#
        )
    }

    fn table() -> InstructionTable {
        InstructionTable::parse(
            text().as_bytes(),
            Path::new("t.json"),
            Mode::Report,
            "zink-testnet",
        )
        .unwrap()
    }

    fn ix(disc: [u8; 8], accounts: &[Address]) -> Instruction {
        Instruction {
            program_id: game(),
            accounts: accounts
                .iter()
                .enumerate()
                .map(|(i, a)| AccountMeta::new(*a, i == 0))
                .collect(),
            data: disc.to_vec(),
        }
    }

    const MOVE: [u8; 8] = [1, 2, 3, 4, 5, 6, 7, 8];
    const CRANK: [u8; 8] = [0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18];

    fn findings(ixs: &[Instruction], profile: Option<&Address>) -> Vec<(&'static str, String)> {
        let m = Message::new(ixs, Some(&addr(1)));
        table()
            .findings(&m, &addr(1), profile)
            .into_iter()
            .map(|r| (r.check, r.detail))
            .collect()
    }

    fn checks(ixs: &[Instruction], profile: Option<&Address>) -> Vec<&'static str> {
        findings(ixs, profile).into_iter().map(|(c, _)| c).collect()
    }

    #[test]
    fn loads_rows_and_refuses_a_wrong_hash_or_cluster() {
        let t = table();
        assert_eq!(t.len(), 2);
        let dir = std::env::temp_dir().join(format!("sfs-itable-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("t.json");
        std::fs::write(&path, text()).unwrap();
        let sum = hex(&Sha256::digest(text().as_bytes()));
        assert!(InstructionTable::load(&path, &sum, Mode::Report, "zink-testnet").is_ok());
        let wrong = InstructionTable::load(&path, &"0".repeat(64), Mode::Report, "zink-testnet");
        assert!(format!("{:#}", wrong.unwrap_err()).contains("sha256"));
        let other = InstructionTable::load(&path, &sum, Mode::Report, "other");
        assert!(format!("{:#}", other.unwrap_err()).contains("cluster"));
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn refuses_a_malformed_table() {
        let parse = |t: &str| {
            InstructionTable::parse(t.as_bytes(), Path::new("t"), Mode::Report, "zink-testnet")
        };
        assert!(parse(&text().replace("\"format\": 1", "\"format\": 2")).is_err());
        assert!(parse(&text().replace("0102030405060708", "01020304")).is_err());
        assert!(
            parse(&text().replace("1112131415161718", "0102030405060708")).is_err(),
            "a duplicate"
        );
        assert!(
            parse(&text().replace("\"min\": 3", "\"min\": 5")).is_err(),
            "min over max"
        );
    }

    #[test]
    fn a_known_instruction_bound_to_the_key_profile_has_no_findings() {
        let ixs = [
            ix(MOVE, &[addr(1), addr(5), addr(6)]),
            ix(CRANK, &[addr(1), addr(7)]),
        ];
        assert!(findings(&ixs, Some(&addr(5))).is_empty());
    }

    #[test]
    fn other_programs_are_not_the_table_s_business() {
        let mut other = ix([9; 8], &[addr(1)]);
        other.program_id = addr(40);
        assert!(findings(&[other], Some(&addr(5))).is_empty());
    }

    #[test]
    fn an_unknown_or_short_discriminator_is_a_finding() {
        let mut short = ix(MOVE, &[addr(1), addr(5), addr(6)]);
        short.data = vec![1, 2];
        let f = findings(&[ix([9; 8], &[addr(1)]), short], Some(&addr(5)));
        assert_eq!(
            f.iter().map(|(c, _)| *c).collect::<Vec<_>>(),
            ["instructions", "instructions"]
        );
        assert!(f[0].1.contains("0909090909090909"), "{}", f[0].1);
    }

    #[test]
    fn too_few_or_too_many_accounts_is_a_finding() {
        let few = ix(MOVE, &[addr(1), addr(5)]);
        let many = ix(CRANK, &[addr(1), addr(7), addr(8)]);
        assert_eq!(
            checks(&[few, many], Some(&addr(5))),
            ["accounts", "accounts"]
        );
        let four = ix(MOVE, &[addr(1), addr(5), addr(6), addr(8)]);
        assert!(
            checks(&[four], Some(&addr(5))).is_empty(),
            "within min and max"
        );
    }

    #[test]
    fn a_group_the_key_signs_for_must_name_its_profile() {
        let elsewhere = ix(MOVE, &[addr(1), addr(9), addr(6)]);
        let f = findings(std::slice::from_ref(&elsewhere), Some(&addr(5)));
        assert_eq!(f.len(), 1);
        assert_eq!(f[0].0, "profile");
        assert!(f[0].1.contains("move"), "{}", f[0].1);
        assert_eq!(
            checks(&[elsewhere], None),
            ["profile"],
            "no profile configured"
        );
    }

    #[test]
    fn a_group_another_key_signs_for_is_not_bound() {
        let mut theirs = ix(MOVE, &[addr(2), addr(9), addr(6)]);
        theirs.accounts[0].is_signer = true;
        assert!(findings(&[theirs], Some(&addr(5))).is_empty());
    }
}
